fn r(p:impl AsRef<Path>)->PathBuf{Path::new(R).join(p)}fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn main(){assert!(!r("native-plan.json").exists());let mut pins:BTreeMap<String,String>=serde_json::from_value(read(r("initial-pins.json"))).unwrap();for(p,h)in&pins{assert_eq!(hash(p),*h);}let mut steps=vec![];for arm in["OFF","ON"]{let mut e=read("/home/ubuntu/src/zopro-perf-work/sdk-link-flags176/environment.json");e["RUSTFLAGS"]=json!(fs::read_to_string(r(format!("{arm}-flags.txt"))).unwrap());e["CARGO_TARGET_DIR"]=json!(r(format!("target-{arm}")));e["CARGO_BUILD_JOBS"]=json!("16");e["RAYON_NUM_THREADS"]=json!("4");let mf=r("source/Cargo.toml");for(name,package,kind)in[("core","zopro-core","--lib"),("prover","zopro-prover","--lib"),("cubic","zopro-prover","cubic")]{let mut argv=vec!["cargo".to_string(),"test".into(),"--manifest-path".into(),mf.display().to_string(),"--release".into(),"--locked".into(),"--offline".into(),"-p".into(),package.into()];if kind=="cubic"{argv.extend(["--test".into(),"cubic".into()]);}else{argv.push(kind.into());}argv.extend(["--".into(),"--test-threads=1".into()]);steps.push(json!({"kind":"command","name":format!("{name}-{arm}"),"argv":argv,"environment":e,"unfiltered":true,"timeout_seconds":1800}));}
 steps.push(json!({"kind":"command","name":format!("libraries-{arm}"),"argv":["cargo","build","--manifest-path",mf,"--release","--locked","--offline","-p","zopro-bench","--lib","--message-format=json"],"environment":e,"timeout_seconds":1800}));steps.push(json!({"kind":"command","name":format!("freeze-{arm}"),"argv":[r("freeze"),"freeze",arm],"environment":e,"timeout_seconds":300}));steps.push(json!({"kind":"link-sdk","name":format!("sdk-{arm}"),"artifacts":r(format!("frozen-{arm}-cargo.jsonl")),"driver":r("driver.rs"),"additional_sources":[r("support/perf.rs")],"additional_rustc_flags":["--cfg","zopro_epoch_clock_api"],"timeout_seconds":1800}));}
 for f in["prepare-native.rs","prepare-native","freeze"]{pins.insert(r(f).display().to_string(),hash(r(f)));}fs::write(r("native-pins.json"),serde_json::to_vec_pretty(&pins).unwrap()).unwrap();fs::write(r("native-plan.json"),serde_json::to_vec_pretty(&json!({"version":1,"source_pins":r("native-pins.json"),"steps":steps})).unwrap()).unwrap();println!("12nativequalification/build/linksteps prepared;newcore128+prover8 perarm;fieldunchanged/inherited");}
